// 全新的游戏/src/services/ship/DockResolver.ts
function resolveDockSpawn(raster, x, z) {
  const isPit = (px, pz) => raster.tileDefAt(px, pz).genRole === "pit";
  if (!isPit(x, z)) return { x, z, y: raster.surfaceHeightAt(x, z), nudged: false };
  const rings = travel_default.dockSearchRings;
  const dirs = travel_default.dockSearchDirs;
  for (const r of rings) {
    for (let i = 0; i < dirs; i++) {
      const a = Math.PI * 2 * i / dirs;
      const px = x + Math.cos(a) * r;
      const pz = z + Math.sin(a) * r;
      if (!isPit(px, pz)) return { x: px, z: pz, y: raster.surfaceHeightAt(px, pz), nudged: true };
    }
  }
  return { x, z, y: raster.surfaceHeightAt(x, z), nudged: false };
}

// 全新的游戏/src/systems/ship/ShipState.ts
function applyShipDamage(session2, amount) {
  const s = session2.ship;
  if (!s || amount <= 0 || s.hp <= 0) return 0;
  let d = amount;
  if (s.shield > 0) {
    const absorbed = Math.min(s.shield, d);
    s.shield -= absorbed;
    d -= absorbed;
  }
  if (d > 0) d = Math.max(1, d - s.armor);
  s.hp = Math.max(0, s.hp - d);
  return d;
}
function damageShip(session2, amount) {
  const actual = applyShipDamage(session2, amount);
  if (actual > 0) {
    eventBus.emit("ship_damaged", {
      damage: actual,
      destroyed: isShipDestroyed(session2)
    });
  }
  return actual;
}
function isShipDestroyed(session2) {
  return !!session2.ship && session2.ship.hp <= 0;
}

// 全新的游戏/src/services/combat/DamagePipeline.ts
var modifierDodge = (ctx) => {
  if (ctx.target.dodgeRate > 0 && Math.random() < ctx.target.dodgeRate) {
    ctx.dodged = true;
    ctx.damage = 0;
  }
};
var modifierBlock = (ctx) => {
  if (ctx.target.blockRate > 0 && Math.random() < ctx.target.blockRate) {
    ctx.blocked = true;
    ctx.damage *= ctx.target.blockMult;
  }
};
var modifierDefense = (ctx) => {
  if (ctx.ignoreDefense) return;
  const atk = ctx.includeSourceAttack ? ctx.source.attackPower : 0;
  ctx.damage = ctx.damage + atk - ctx.target.defense;
};
var modifierDamageReduction = (ctx) => {
  const dr = Math.max(0, Math.min(0.9, ctx.target.damageReduction));
  if (dr > 0) ctx.damage *= 1 - dr;
};
var modifierCrit = (ctx) => {
  if (ctx.source.critRate > 0 && Math.random() < ctx.source.critRate) {
    ctx.crit = true;
    ctx.damage *= ctx.source.critMult;
  }
};
var PIPELINE = [
  modifierDodge,
  modifierBlock,
  modifierDefense,
  modifierDamageReduction,
  modifierCrit
];
function normalize2(raw) {
  return raw > 0 ? Math.max(1, Math.round(raw)) : 0;
}
function resolveDamage(base, source, target, opts = {}) {
  const ctx = {
    base,
    source,
    target,
    type: opts.type ?? "physical",
    includeSourceAttack: opts.includeSourceAttack ?? false,
    ignoreDefense: opts.ignoreDefense ?? false,
    damage: base,
    crit: false,
    dodged: false,
    blocked: false
  };
  for (const m of PIPELINE) {
    m(ctx);
    if (ctx.dodged || ctx.damage <= 0) break;
  }
  return { final: normalize2(ctx.damage), crit: ctx.crit, dodged: ctx.dodged, blocked: ctx.blocked };
}
function applyDamage(base, source, target, opts = {}) {
  const r = resolveDamage(base, source, target, opts);
  if (!r.dodged && r.final > 0) target.onTakeDamage(r.final, source, opts.hitPoint);
  eventBus.emit("damage", {
    target,
    source,
    damage: r.final,
    crit: r.crit,
    dodged: r.dodged,
    blocked: r.blocked,
    type: opts.type ?? "physical"
  });
  return r;
}

// 全新的游戏/src/systems/combat/KillCounter.ts
function emptyEnemyProgress() {
  return { quota: 0, kills: 0, recalled: 0, spawned: 0 };
}
function readDayProgress(session2) {
  if (!session2) return emptyEnemyProgress();
  const dp = session2.dayProgress;
  return dp.enemies ?? emptyEnemyProgress();
}
function recordSpawn(session2, count = 1) {
  if (!session2 || count <= 0) return;
  const dp = session2.dayProgress;
  if (!dp.enemies) dp.enemies = { quota: 0, kills: 0, recalled: 0, spawned: 0 };
  if (typeof dp.enemies.spawned !== "number") dp.enemies.spawned = 0;
  dp.enemies.spawned += count;
}
function remainingQuota(session2) {
  const e = readDayProgress(session2);
  const spawned2 = typeof e.spawned === "number" ? e.spawned : 0;
  return Math.max(0, e.quota - spawned2);
}

