// 全新的游戏/src/services/fx/FootAnchor.ts
function footSinkRatioOf(source, frameIndex = 0) {
  const img = source.getFramePair(frameIndex)?.base?.image;
  const data = img?.data;
  const w = img?.width ?? 0;
  const h = img?.height ?? 0;
  if (!data || w <= 0 || h <= 0) return 0;
  if (data.length < w * h * 4) return 0;
  const isFloat = data instanceof Float32Array;
  const opaque = isFloat ? 0.5 : 128;
  let lastOpaque = -1;
  for (let y = h - 1; y >= 0 && lastOpaque < 0; y--) {
    const rowBase = y * w * 4;
    for (let x = 0; x < w; x++) {
      if (data[rowBase + x * 4 + 3] >= opaque) {
        lastOpaque = y;
        break;
      }
    }
  }
  if (lastOpaque < 0) return 0;
  return (h - 1 - lastOpaque) / w;
}

